import{_ as a,o as t,c as i,ao as s}from"./chunks/framework.CGAfXaNK.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"MTGeophysics.jl","tagline":"A software repository for magnetotelluric geophysics research and applications.","actions":[{"theme":"brand","text":"Getting Started","link":"/getting_started"},{"theme":"alt","text":"Forward modelling","link":"/forward/2d"},{"theme":"alt","text":"View on GitHub","link":"https://github.com/JuliaGeophysics/MTGeophysics.jl"}]},"features":[{"title":"Forward modelling","details":"Exact 1D layered-earth responses and a 2D TE/TM finite-difference solver with topography and lakes. 3D runs through ModEM.","link":"/forward/2d"},{"title":"Deterministic inversion","details":"Gauss–Newton and NLCG in 1D and 2D, set up from a handful of small text files.","link":"/inversion/2d_deterministic"},{"title":"VFSA inversion","details":"Very fast simulated annealing in 1D, 2D and 3D. Several chains give an ensemble of models and an estimate of uncertainty.","link":"/inversion/2d_vfsa"},{"title":"Data and meshes","details":"Read and rotate ModEM data files, and build 2D and 3D meshes with topography and water from a data file.","link":"/data/files"},{"title":"Interactive 3D viewers","details":"Depth slices, cross-sections, phase tensor maps and model editors, with shapefile overlays and GIS export.","link":"/visualisation/3d_models"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":null}'),n={name:"index.md"};function o(l,e,r,d,p,h){return t(),i("div",null,[...e[0]||(e[0]=[s('<h2 id="What-is-MTGeophysics.jl?" tabindex="-1">What is MTGeophysics.jl? <a class="header-anchor" href="#What-is-MTGeophysics.jl?" aria-label="Permalink to &quot;What is MTGeophysics.jl? {#What-is-MTGeophysics.jl?}&quot;">​</a></h2><p>MTGeophysics.jl is part of the <a href="https://github.com/JuliaGeophysics" target="_blank" rel="noreferrer">JuliaGeophysics ecosystem</a> and is intended for both research and real-world applications. It provides reusable forward-modelling, inversion, and visualization components so you can prototype new machine-learning methods, inversion strategies, and data-analysis ideas quickly without rebuilding core MT tooling from scratch. More broadly, JuliaGeophysics aims to build a tightly integrated yet modular ecosystem for multiphysics workflows, multisource data integration, and uncertainty quantification.</p><h2 id="Install" tabindex="-1">Install <a class="header-anchor" href="#Install" aria-label="Permalink to &quot;Install {#Install}&quot;">​</a></h2><div class="language-julia vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">julia</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;" class="repl-prompt repl-prompt-pkg">pkg</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;" class="repl-prompt repl-prompt-pkg">&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> add MTGeophysics</span></span></code></pre></div><p>Then see <a href="./getting_started">Getting Started</a> to run your first forward model and inversion.</p>',5)])])}const u=a(n,[["render",o]]);export{m as __pageData,u as default};
